#!/usr/bin/env bash
set -euo pipefail
[[ -d .git && -f pubspec.yaml && -f desktop/hyper_player/VISUAL_ALIGNMENT_7.md ]] || { echo 'Run in your repository root after the seventh Android visual-alignment update.' >&2; exit 1; }
python3 - <<'VISUAL_GROUP_EIGHT'
from pathlib import Path
import base64
files = {
'desktop/hyper_player/lib/main.dart': '',
'desktop/hyper_player/lib/screens/media_info_sheet.dart': '',
'desktop/hyper_player/test/media_info_sheet_test.dart': '',
'desktop/hyper_player/VISUAL_ALIGNMENT_8.md': '',
}
for name, data in files.items():
    p = Path(name)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(base64.b64decode(data))
print('Android-style Video info and A–B repeat panels installed. Android unchanged.')
VISUAL_GROUP_EIGHT
